using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.Refresh(ImportAssetOptions.ForceUpdate);
        AssetDatabase.SaveAssets();
        result.Log("Refreshed.");
        string[] paths = {
            "Assets/Resources/HUDTree/Fonts/HomesteaderHUD.ttf",
            "Assets/Resources/HUDTree/Fonts/HomesteaderHUD_Medium.ttf",
            "Assets/Resources/HUDTree/Fonts/HomesteaderHUD_Bold.ttf",
            "Assets/Resources/HUDTree/Fonts/HomesteaderHUD_Italic.ttf",
            "Assets/Resources/HUDTree/Fonts/HomesteaderHUD_BoldItalic.ttf",
        };
        foreach (var p in paths)
        {
            var exists = System.IO.File.Exists(p);
            var meta = System.IO.File.Exists(p + ".meta");
            var font = exists ? AssetDatabase.LoadAssetAtPath<Font>(p) : null;
            if (font != null)
            {
                result.Log("  " + p + " -> ok, name=" + font.name + " dynamic=" + font.dynamic);
            }
            else
            {
                result.Log("  " + p + " -> font is null");
            }
        }
        var fsrReg = Resources.Load<Font>("HUDTree/Fonts/HomesteaderHUD");
        result.Log("Resources.Load HUDTree/Fonts/HomesteaderHUD -> " + (fsrReg == null ? "NULL" : ("ok name=" + fsrReg.name)));
        var fsrMed = Resources.Load<Font>("HUDTree/Fonts/HomesteaderHUD_Medium");
        result.Log("Resources.Load _Medium -> " + (fsrMed == null ? "NULL" : "ok"));
        var fsrBold = Resources.Load<Font>("HUDTree/Fonts/HomesteaderHUD_Bold");
        result.Log("Resources.Load _Bold -> " + (fsrBold == null ? "NULL" : "ok"));
    }
}
